// Writes desktop/Flowy.Core/LookData.cs from src/core/look.ts and src/core/icons.ts, so the app draws the shapes, colours and
// icons the browser does. Run from the repo root after changing either file: node desktop/tools/make-look-data.ts
import { writeFileSync } from 'node:fs'
import { ICON_GROUPS, ICONS } from '../../src/core/icons.ts'
import { COLORS, SHAPE_DEFS } from '../../src/core/look.ts'

const str = (s: string) => JSON.stringify(s) // C# and JSON escape a plain string the same way
const lines = [
  '// Generated by desktop/tools/make-look-data.ts from src/core/look.ts and src/core/icons.ts. Do not edit; change those and run the script again.',
  '// Icons from Tabler Icons, https://tabler.io/icons. MIT License, Copyright (c) 2020-2024 Paweł Kuna. The notice ships as',
  '// Assets/TABLER-ICONS-LICENSE.txt next to the program. Each is drawn on a 24-unit grid with a 2-unit round stroke.',
  'namespace Flowy.Core;',
  '',
  '/// <summary>One shape: its outline in the 200×72 area every shape is drawn in, where content may sit (top, right, bottom, left), where "3 inside" goes (right, bottom), whether the icon tile shows without an icon of its own, and the outline as a convex polygon (x0, y0, x1, y1, …; empty is the rectangle) where straight lines meet it.</summary>',
  'public sealed record ShapeDef(string Path, int[] Pad, int[] Badge, bool Tile, double[] Edge);',
  '',
  '/// <summary>What the shapes, the named colours and the built-in icons are, as src/core/look.ts and src/core/icons.ts say.</summary>',
  'public static class LookData',
  '{',
  '    public static readonly IReadOnlyDictionary<string, ShapeDef> Shapes = new Dictionary<string, ShapeDef>',
  '    {',
  ...Object.entries(SHAPE_DEFS).map(([name, d]) => `        [${str(name)}] = new(${str(d.path)}, [${d.pad.join(', ')}], [${d.badge.join(', ')}], ${d.tile}, [${d.edge.flat().join(', ')}]),`),
  '    };',
  '',
  '    /// <summary>Name → [light theme, dark theme].</summary>',
  '    public static readonly IReadOnlyDictionary<string, string[]> Colors = new Dictionary<string, string[]>',
  '    {',
  ...Object.entries(COLORS).map(([name, pair]) => `        [${str(name)}] = [${pair.map(str).join(', ')}],`),
  '    };',
  '',
  '    public static readonly IReadOnlyDictionary<string, string> Icons = new Dictionary<string, string>',
  '    {',
  ...Object.entries(ICONS).map(([name, d]) => `        [${str(name)}] = ${str(d)},`),
  '    };',
  '',
  '    public static readonly (string Group, string[] Names)[] IconGroups =',
  '    [',
  ...ICON_GROUPS.map(g => `        (${str(g.group)}, [${g.names.map(str).join(', ')}]),`),
  '    ];',
  '}',
  '',
]
writeFileSync(new URL('../Flowy.Core/LookData.cs', import.meta.url), lines.join('\n'))
console.log(`wrote ${Object.keys(SHAPE_DEFS).length} shapes, ${Object.keys(COLORS).length} colours, ${Object.keys(ICONS).length} icons`)
